#!/usr/bin/env python3
"""
Match gamma ray energies between 2012DI06 and 2025LAAA datasets for 127I
Creates combined table with nuclear structure information
"""

import json
import sys

def load_2025_gammas(json_file):
    """Load gamma energies from 2025LAAA JSON file"""
    with open(json_file, 'r') as f:
        data = json.load(f)
    
    gammas = []
    for transition in data['gamma_transitions']:
        energy = transition['energy']['value']
        status = transition.get('status', 'matched')
        gammas.append({'energy': energy, 'status': status})
    
    return gammas

