def match_gamma_energies(data_2012, gammas_2025, tolerance=0.8):
    """Match gamma energies between 2012 and 2025 datasets"""
    matches = []
    unmatched_2012 = []
    unmatched_2025 = list(gammas_2025)  # Copy to track unmatched
    
    for transition_2012 in data_2012:
        eli, ji, elf, jf, eg_2012, ri_2012 = transition_2012
        
        # Find matching energy in 2025 data
        best_match = None
        best_diff = float('inf')
        
        for i, gamma_2025 in enumerate(gammas_2025):
            diff = abs(eg_2012 - gamma_2025['energy'])
            if diff <= tolerance and diff < best_diff:
                best_match = i
                best_diff = diff
        
        if best_match is not None:
            # Found a match
            gamma_2025 = gammas_2025[best_match]
            matches.append({
                'eli': eli,
                'ji': ji,
                'elf': elf,
                'jf': jf,
                'eg_2012': eg_2012,
                'ri_2012': ri_2012,
                'eg_2025': gamma_2025['energy'],
                'status_2025': gamma_2025['status'],
                'diff': best_diff
            })
            # Remove from unmatched list
            if gamma_2025 in unmatched_2025:
                unmatched_2025.remove(gamma_2025)
        else:
            # No match found
            unmatched_2012.append({
                'eli': eli,
                'ji': ji,
                'elf': elf,
                'jf': jf,
                'eg_2012': eg_2012,
                'ri_2012': ri_2012
            })
    
    return matches, unmatched_2012, unmatched_2025

def print_combined_table(matches):
    """Print the combined table in requested format"""
    print("=" * 85)
    print("COMBINED 2012DI06 AND 2025LAAA GAMMA RAY DATA FOR 127I")
    print("=" * 85)
    print(f"{'ELI':>8} {'JI':>8} {'ELF':>8} {'JF':>8} {'EG_2012':>8} {'RI_2012':>12} {'EG_2025':>8} {'DIFF':>6}")
    print(f"{'(keV)':>8} {'':>8} {'(keV)':>8} {'':>8} {'(keV)':>8} {'':>12} {'(keV)':>8} {'(keV)':>6}")
    print("-" * 85)
    
    # Sort by initial level energy, then gamma energy
    sorted_matches = sorted(matches, key=lambda x: (x['eli'], x['eg_2012']))
    
    for match in sorted_matches:
        print(f"{match['eli']:8.2f} {match['ji']:>8} {match['elf']:8.2f} {match['jf']:>8} "
              f"{match['eg_2012']:8.1f} {match['ri_2012']:>12} {match['eg_2025']:8.1f} {match['diff']:6.1f}")

def print_unmatched_summary(unmatched_2012, unmatched_2025):
    """Print summary of unmatched transitions"""
    print("\n" + "=" * 60)
    print("UNMATCHED TRANSITIONS SUMMARY")
    print("=" * 60)
    
    if unmatched_2012:
        print(f"\n2012DI06 transitions NOT found in 2025LAAA ({len(unmatched_2012)} total):")
        print(f"{'EG_2012':>8} {'ELI':>8} {'JI':>8} {'ELF':>8} {'JF':>8} {'RI_2012':>12}")
        print("-" * 60)
        for t in sorted(unmatched_2012, key=lambda x: x['eg_2012']):
            print(f"{t['eg_2012']:8.1f} {t['eli']:8.2f} {t['ji']:>8} {t['elf']:8.2f} {t['jf']:>8} {t['ri_2012']:>12}")
    
    if unmatched_2025:
        print(f"\n2025LAAA energies NOT found in 2012DI06 ({len(unmatched_2025)} total):")
        print(f"{'EG_2025':>8} {'STATUS':>15}")
        print("-" * 25)
        for gamma in sorted(unmatched_2025, key=lambda x: x['energy']):
            status = gamma.get('status', 'unmatched')
            print(f"{gamma['energy']:8.1f} {status:>15}")

def main():
    # Load data
    gammas_2025 = load_2025_gammas('XUNDL/2025LAAA_CH11036_127I_gamma_energies.json')
    data_2012 = parse_2012_data()
    
    print(f"Loaded {len(data_2012)} transitions from 2012DI06")
    print(f"Loaded {len(gammas_2025)} gamma energies from 2025LAAA")
    
    # Match gamma energies
    matches, unmatched_2012, unmatched_2025 = match_gamma_energies(data_2012, gammas_2025, tolerance=0.8)
    
    print(f"\nFound {len(matches)} matched transitions")
    print(f"Unmatched 2012DI06: {len(unmatched_2012)}")
    print(f"Unmatched 2025LAAA: {len(unmatched_2025)}")
    
    # Print results
    print_combined_table(matches)
    print_unmatched_summary(unmatched_2012, unmatched_2025)
    
    # Statistics
    print("\n" + "=" * 60)
    print("MATCHING STATISTICS")
    print("=" * 60)
    print(f"Total 2012DI06 transitions: {len(data_2012)}")
    print(f"Total 2025LAAA gammas: {len(gammas_2025)}")
    print(f"Successfully matched: {len(matches)} ({100*len(matches)/len(data_2012):.1f}% of 2012DI06)")
    print(f"2025LAAA coverage: {len(matches)} of {len(gammas_2025)} ({100*len(matches)/len(gammas_2025):.1f}%)")
    
    if len(unmatched_2025) > 0:
        new_transitions = [g for g in unmatched_2025 if g.get('status') == 'new_transition']
        print(f"New transitions in 2025LAAA: {len(new_transitions)}")

if __name__ == "__main__":
    main()
